namespace HawalekNow.Application.Shared.Storage;

public sealed record StoredImage(string Key, int Width, int Height, long Length, DateTimeOffset CreatedAt);

public interface IFileStorage
{
    // Keys are generated by the server; a filename, URL or user-supplied path is never accepted.
    Task<StoredImage> WriteImageAsync(string key, Stream input, CancellationToken cancellationToken);
    Task<byte[]?> ReadImageAsync(string key, CancellationToken cancellationToken);
    Task DeleteOwnedAsync(string key, CancellationToken cancellationToken);
    IAsyncEnumerable<StoredImage> OldImagesAsync(DateTimeOffset olderThan, CancellationToken cancellationToken);
}

public sealed class InvalidImageException() : Exception("The image is invalid.");
public sealed class StorageIntegrityException() : IOException("Storage ownership or integrity could not be verified.");

public static class ImageStorageLimits
{
    public const int MaxInputBytes = 2 * 1024 * 1024;
    public const int MaxStoredBytes = 8 * 1024 * 1024;
    public const int MaxDimension = 2048;
    public static bool ValidKey(string? value) => value is { Length: 32 } && value.All(character => character is >= '0' and <= '9' or >= 'a' and <= 'f');
}
